SELECT /*selectBuyerMpRqUnitpriceAgrmntNegoReqMultiList*/ Z.BTOA_DATE, REPLACE(Z.DESCRIPTION,'"','˝') AS DESCRIPTION , Z.UNIT_MEASURE, Z.MAKER_NAME, Z.AGENT, Z.BTOA_USER_NAME, Z.KEP_USER_ID, Z.SOURCING_STATUS, Z.BUYER_ITEM_NO, Z.BTOA_END_DATE, REPLACE(Z.SPECIFICATION,'"','˝') AS SPECIFICATION , Z.ITEM_QTY, Z.ORIGIN_NAME, Z.BUYER_TARGET_PRICE, Z.ATOB_UNIT_PRICE, Z.BTOA_USER_DEPT, REPLACE(Z.ATOB_REMARK, '"','″') AS ATOB_REMARK, Z.IMAGE_KEY, Z.BUYER, Z.QUOTATION_NO, Z.QUOTATION_SEQ, Z.REVISION, Z.KEP_USER_NAME, Z.AGENT_NAME, Z.REG_ITEM_NO, Z.CONTRACT_NO, Z.CONTRACT_SEQ, Z.BYCA_COMORG_CODE, Z.BUYER_NAME, Z.BTOA_END_TIME, Z.BTOA_REMARK, Z.AGENT_OPEN_FLAG, Z.STOA_LIST_PRICE, Z.ORIGIN_CODE, Z.LEAD_TIME, Z.LOAD_USER_ID, Z.ATOB_DATE, Z.CMS_CATEG_ID, Z.CMS_CATLG_ID, Z.PROCESS_TYPE, Z.IMPORT_FLAG, Z.WAREHOUSE_CODE, Z.BELOW_COMORG_CODE, Z.ITEM_GROUP , Z.ITEM_DETAIL_DESC , Z.IMGFILE_NAME , (SELECT PRODUCT_CLOSE_FLAG FROM ICOMBYIT WHERE BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = Z.BUYER AND STATUS IN ('C','R')) AND BUYER_ITEM_NO = Z.BUYER_ITEM_NO ) AS PRODUCT_CLOSE_FLAG , DECODE(SUBSTR(Z.BUYER_ITEM_NO,1,7),'NO_CODE','Y','N') AS NOCODE_YN , Z.ITEM_TYPE , Z.ITEM_TYPE_TEXT , Z.GREEN_FLAG , Z.ITEM_GUBUN , Z.RE_ITEM_NO , Z.REG_ITEM_NO2 , Z.MSDS_YN , Z.MSDS_NO , Z.MSDS_STATUS , Z.MSDS_TYPE_TEXT , Z.REQ_PRICE_TYPE , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M150' AND CODE = Z.REQ_PRICE_TYPE) AS REQ_PRICE_TYPE_TEXT , Z.IMGFILE_DIR , Z.SELL_CLOSE_DATE , Z.BUY_CLOSE_DATE , Z.MIN_ORDER_QTY , Z.PUR_UNIT_QTY FROM( SELECT ROWNUM NUM, Y.BTOA_DATE, Y.DESCRIPTION, Y.UNIT_MEASURE, Y.MAKER_NAME, Y.AGENT, Y.BTOA_USER_NAME, Y.KEP_USER_ID, Y.SOURCING_STATUS, Y.BUYER_ITEM_NO, Y.BTOA_END_DATE, Y.SPECIFICATION, Y.ITEM_QTY, Y.ORIGIN_NAME, Y.BUYER_TARGET_PRICE, Y.ATOB_UNIT_PRICE, Y.BTOA_USER_DEPT, Y.ATOB_REMARK, Y.IMAGE_KEY, Y.BUYER, Y.QUOTATION_NO, Y.QUOTATION_SEQ, Y.REVISION, Y.KEP_USER_NAME, Y.AGENT_NAME, Y.REG_ITEM_NO, Y.CONTRACT_NO, Y.CONTRACT_SEQ, Y.BYCA_COMORG_CODE, Y.BUYER_NAME, Y.BTOA_END_TIME, Y.BTOA_REMARK, Y.AGENT_OPEN_FLAG, Y.STOA_LIST_PRICE, Y.ORIGIN_CODE, Y.LEAD_TIME, Y.LOAD_USER_ID, Y.ATOB_DATE, Y.CMS_CATEG_ID, Y.CMS_CATLG_ID, Y.PROCESS_TYPE, Y.IMPORT_FLAG, Y.WAREHOUSE_CODE, Y.BELOW_COMORG_CODE, Y.ITEM_GROUP , Y.ITEM_DETAIL_DESC , Y.IMGFILE_NAME , Y.ITEM_TYPE , Y.ITEM_TYPE_TEXT , Y.GREEN_FLAG , Y.ITEM_GUBUN , Y.RE_ITEM_NO , Y.REG_ITEM_NO2 , Y.MSDS_YN , Y.MSDS_NO , Y.MSDS_STATUS , Y.MSDS_TYPE_TEXT , Y.REQ_PRICE_TYPE , Y.IMGFILE_DIR , Y.SELL_CLOSE_DATE , Y.BUY_CLOSE_DATE , Y.MIN_ORDER_QTY , Y.PUR_UNIT_QTY FROM( SELECT X.BTOA_DATE, X.DESCRIPTION, X.UNIT_MEASURE, X.MAKER_NAME, X.AGENT, X.BTOA_USER_NAME, X.KEP_USER_ID, X.SOURCING_STATUS, X.BUYER_ITEM_NO, X.BTOA_END_DATE, X.SPECIFICATION, X.ITEM_QTY, X.ORIGIN_NAME, X.BUYER_TARGET_PRICE, X.ATOB_UNIT_PRICE, X.BTOA_USER_DEPT, X.ATOB_REMARK, X.IMAGE_KEY, X.BUYER, X.QUOTATION_NO, X.QUOTATION_SEQ, X.REVISION, X.KEP_USER_NAME, X.AGENT_NAME, X.REG_ITEM_NO, X.CONTRACT_NO, X.CONTRACT_SEQ, X.BYCA_COMORG_CODE, X.BUYER_NAME, X.BTOA_END_TIME, X.BTOA_REMARK, X.AGENT_OPEN_FLAG, X.STOA_LIST_PRICE, X.ORIGIN_CODE, X.LEAD_TIME, X.LOAD_USER_ID, X.ATOB_DATE, NVL(TRIM(X.CMS_CATEG_ID), 'NO_CATEG') AS CMS_CATEG_ID, NVL(TRIM(X.CMS_CATLG_ID), 'NO_CATLG') AS CMS_CATLG_ID, X.PROCESS_TYPE, X.IMPORT_FLAG, X.WAREHOUSE_CODE, X.BELOW_COMORG_CODE, X.ITEM_GROUP , X.ITEM_DETAIL_DESC , X.IMGFILE_NAME , X.ITEM_TYPE , X.ITEM_TYPE_TEXT , X.GREEN_FLAG , X.ITEM_GUBUN , X.REG_ITEM_NO2 , DECODE(X.RE_ITEM_NO,NULL,'',SUBSTR(X.RE_ITEM_NO,12,6)) AS RE_ITEM_NO , X.MSDS_YN , X.MSDS_STATUS , X.MSDS_NO , X.MSDS_TYPE_TEXT , X.REQ_PRICE_TYPE , X.IMGFILE_DIR , X.SELL_CLOSE_DATE , X.BUY_CLOSE_DATE , X.MIN_ORDER_QTY , X.PUR_UNIT_QTY FROM( SELECT MAX(A.BTOA_DATE) AS BTOA_DATE, MAX(A.DESCRIPTION) AS DESCRIPTION, MAX(A.UNIT_MEASURE) AS UNIT_MEASURE, MAX(A.MAKER_NAME) AS MAKER_NAME, MAX(B.AGENT) AS AGENT, MAX(A.BTOA_USER_NAME) AS BTOA_USER_NAME, MAX(A.KEP_USER_ID) AS KEP_USER_ID, MAX(DECODE(A.RECV_FLAG,'GR','결재반려',DECODE(NVL(A.BTOA_NEGO_PRICE,0),0,'합의대상', 'Nego합의대상'))) AS SOURCING_STATUS, MAX(A.BUYER_ITEM_NO) AS BUYER_ITEM_NO, MAX(A.BTOA_END_DATE) AS BTOA_END_DATE, MAX(SUBSTR(NVL(A.BTOA_END_TIME,'19'),0,2))||':'||MAX(SUBSTR(NVL(A.BTOA_END_TIME,'00'),3,2)) AS BTOA_END_TIME, MAX(A.SPECIFICATION) AS SPECIFICATION, MAX(NVL(A.ITEM_QTY,0)) AS ITEM_QTY, MAX((SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = A.ORIGIN_CODE)) AS ORIGIN_NAME, MAX(NVL(A.BUYER_TARGET_PRICE,0)) AS BUYER_TARGET_PRICE, MAX(NVL(A.ATOB_UNIT_PRICE,0)) AS ATOB_UNIT_PRICE, MAX((SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND TYPE = 'C001' AND CODE = A.BTOA_USER_DEPT)) AS BTOA_USER_DEPT, MAX(TRIM(A.ATOB_REMARK)) AS ATOB_REMARK, MAX(TRIM(A.IMAGE_KEY)) AS IMAGE_KEY, A.BUYER, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION, MAX((SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.KEP_USER_ID)) AS KEP_USER_NAME, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=B.AGENT)) AS AGENT_NAME, MAX(A.REG_ITEM_NO) AS REG_ITEM_NO, MAX(A.CONTRACT_NO) AS CONTRACT_NO, MAX(A.CONTRACT_SEQ) AS CONTRACT_SEQ, MAX((SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = A.BUYER AND STATUS IN ('C','R'))) AS BYCA_COMORG_CODE, MAX((SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER)) AS BUYER_NAME, MAX(NVL(TRIM(A.BTOA_REMARK),'')) AS BTOA_REMARK, MAX(A.AGENT_OPEN_FLAG) AS AGENT_OPEN_FLAG, MAX(B.STOA_LIST_PRICE) AS STOA_LIST_PRICE, MAX(A.ORIGIN_CODE) AS ORIGIN_CODE, MAX(B.LEAD_TIME) AS LEAD_TIME, MAX(A.LOAD_USER_ID) AS LOAD_USER_ID, MAX(A.ATOB_DATE) AS ATOB_DATE, MAX(A.CMS_CATEG_ID) AS CMS_CATEG_ID, MAX(A.CMS_CATLG_ID) AS CMS_CATLG_ID, MAX(A.PROCESS_TYPE) AS PROCESS_TYPE, MAX(A.IMPORT_FLAG) AS IMPORT_FLAG, MAX(NVL(A.WAREHOUSE_CODE,'')) AS WAREHOUSE_CODE, MAX(A.BELOW_COMORG_CODE) AS BELOW_COMORG_CODE, MAX(A.ITEM_GROUP) AS ITEM_GROUP , MAX(A.ITEM_DETAIL_DESC) AS ITEM_DETAIL_DESC , MAX(DECODE(A.ITEM_TYPE,'T','계약요청품목','O','일회성품목','N','미분류')) AS ITEM_TYPE_TEXT , MAX(A.ITEM_TYPE) AS ITEM_TYPE , MAX(NVL(A.GREEN_FLAG,'N')) AS GREEN_FLAG , MAX(A.ITEM_GUBUN) AS ITEM_GUBUN , MAX(SUBSTR(A.REG_ITEM_NO,0,10)) AS REG_ITEM_NO2 ,MAX((SELECT ITEM_NO FROM ICOMCQDT CQDT WHERE CQDT.BUYER = A.BUYER AND CQDT.BUYER_ITEM_NO = A.BUYER_ITEM_NO AND CQDT.CONTRACT_NO = A.CONTRACT_NO AND CQDT.CONTRACT_SEQ = A.CONTRACT_SEQ AND CQDT.STATUS IN ('C','R') ) ) RE_ITEM_NO , MAX(NVL(DECODE(A.MSDS_NO, 'MS88888888', 'N', 'MS99999999', 'N', A.MSDS_YN),'N')) AS MSDS_YN , MAX(DECODE(A.MSDS_NO, 'MS88888888', 'N', 'MS99999999', 'N', A.MSDS_STATUS)) AS MSDS_STATUS , MAX(DECODE(A.MSDS_NO, 'MS88888888', '', 'MS99999999', '', A.MSDS_NO)) AS MSDS_NO , MAX(DECODE(NVL(DECODE(A.MSDS_NO, 'MS88888888', 'N', 'MS99999999', 'N', A.MSDS_YN),'N')||A.MSDS_STATUS,'YC','MSDS제출','YT','MSDS검토','YA','MSDS승인')) AS MSDS_TYPE_TEXT , MAX(REQ_PRICE_TYPE) AS REQ_PRICE_TYPE , DECODE(MAX(A.RFQ_IMG_TYPE), 'M', MAX(A.IMGFILE_DIR), MAX(B.IMGFILE_DIR)) AS IMGFILE_DIR , DECODE(MAX(A.RFQ_IMG_TYPE), 'M', MAX(A.IMGFILE_NAME), MAX(B.IMGFILE_NAME)) AS IMGFILE_NAME , MAX(A.SELL_CLOSE_DATE) AS SELL_CLOSE_DATE , MAX(A.BUY_CLOSE_DATE) AS BUY_CLOSE_DATE , MAX(B.MIN_ORDER_QTY) AS MIN_ORDER_QTY , MAX(B.PUR_UNIT_QTY) AS PUR_UNIT_QTY FROM KEPRQDT A, KEPQTDT B WHERE 1=1 AND A.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TCFM' AND COD3.CODE1 = #{st_com_code} AND FLAG = 'Y') AND A.SO_CA_FLAG='SO'
AND A.ATOB_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BTOA_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BTOA_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BUYER=B.BUYER AND A.QUOTATION_NO=B.QUOTATION_NO AND A.QUOTATION_SEQ=B.QUOTATION_SEQ AND A.REVISION=B.REVISION AND B.BID_SUCCESS_FLAG = 'Y' AND A.ATOB_UNIT_PRICE <> 0 AND A.CONFIRM_DATE IS NULL AND A.RECV_FLAG IN ('GA','GR') AND A.ATOB_SEND_FLAG = 'Y' AND A.STATUS IN ('C','R') AND B.STATUS <> 'D' AND B.STATUS <> 'O' AND NVL(A.MSDS_STATUS,'N') <> 'R'
AND A.QUOTATION_NO LIKE '%' || #{st_quotation_no} || '%'
AND A.BUYER_ITEM_NO LIKE '%' || #{st_buyer_item_no} || '%'
AND A.BTOA_USER_NAME LIKE '%' || #{st_btoa_user_name} || '%'
AND A.BTOA_USER_DEPT = #{st_btoa_user_dept_code}
AND DECODE(A.RECV_FLAG,'GR','결재반려',DECODE(NVL(A.BTOA_NEGO_PRICE,0),0,(CASE WHEN NVL(DECODE(A.MSDS_NO, 'MS88888888', 'N', 'MS99999999', 'N', A.MSDS_YN),'N')= 'N' OR MSDS_STATUS NOT IN ('C', 'T') THEN '합의대상 (MSDS 미승인 제외)' ELSE '합의대상' END), 'Nego합의대상')) LIKE #{st_sourcing_status} ||'%'
AND A.BUYER = #{st_buyer_select}
AND (A.DESCRIPTION LIKE '%' || #{st_desc_spec} || '%' OR A.SPECIFICATION LIKE '%' || #{st_desc_spec} || '%' )
AND A.BTOA_USER_ID = #{st_user_id}
AND DECODE(A.MSDS_NO, 'MS88888888', 'N', 'MS99999999', 'N', A.MSDS_YN) = 'Y' AND DECODE(A.MSDS_NO, 'MS88888888', 'N', 'MS99999999', 'N', A.MSDS_STATUS) = 'C'
AND DECODE(A.MSDS_NO, 'MS88888888', 'N', 'MS99999999', 'N', A.MSDS_YN) = 'Y' AND DECODE(A.MSDS_NO, 'MS88888888', 'N', 'MS99999999', 'N', A.MSDS_STATUS) = 'T'
AND DECODE(A.MSDS_NO, 'MS88888888', 'N', 'MS99999999', 'N', A.MSDS_YN) = 'Y' AND DECODE(A.MSDS_NO, 'MS88888888', 'N', 'MS99999999', 'N', A.MSDS_STATUS) = 'A'
GROUP BY A.BUYER, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION ORDER BY A.BUYER, A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION ) X
ORDER BY X.ATOB_DATE DESC
ORDER BY X.QUOTATION_NO DESC
ORDER BY X.BTOA_DATE DESC
) Y ) Z

mapper.update:

UPDATE KEPRQDT			/*updateNegoBuyerRqdtMulti*/		
   SET ATOB_UNIT_PRICE = 0		
     , BTOA_NEGO_PRICE = #{st_btoa_nego_price2}
     , BTOA_END_DATE   = #{st_btoa_end_date2}
     , BTOA_END_TIME   = #{st_btoa_end_time2}
     , REJECT_REMARK   = #{st_reject_remark2}
     , RECV_FLAG       = 'GA'	
 WHERE BUYER         = #{st_buyer2}
   AND QUOTATION_NO  = #{st_quotation_no2}
   AND QUOTATION_SEQ = #{st_quotation_seq2}
   AND REVISION      = #{st_revision2}
   AND RECV_FLAG  IN ('GA','GR')	
   AND STATUS IN ('C','R')


UPDATE KEPQTDT		/*updateNegoBuyerQtdtMulti*/			
   SET BTOA_NEGO_PRICE = #{st_btoa_nego_price2}
 WHERE BUYER         = #{st_buyer2}
   AND QUOTATION_NO  = #{st_quotation_no2}
   AND QUOTATION_SEQ = #{st_quotation_seq2}
   AND REVISION      = #{st_revision2}
   AND STATUS IN ('C','R')


UPDATE KEPRQDT		/*updateNsCancelKEPRQDTMulti*/			
   SET RECV_FLAG = #{RECV_FLAG}
 WHERE BUYER = #{KEY_2}
   AND GW_NO = #{KEY_1}


	UPDATE KEPRQDT		/*updateNsApproval1Multi*/			
       SET CONFIRM_DATE=TO_CHAR(SYSDATE, 'YYYYMMDD'),    
           CONFIRM_TIME=TO_CHAR(SYSDATE, 'HHMMSS'),    
           CONFIRM_USER_ID = #{USER_ID},    
           RECV_FLAG = #{RECV_FLAG}  
    WHERE BUYER = #{KEY_2}    
      AND GW_NO = #{KEY_1}    
      AND STATUS IN ('C','R')


UPDATE ICOMBYIT /*updateNsApproval_BYITMulti*/
	SET BUYER_ITEM_NO = #{BUYER_ITEM_NO}
WHERE BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=#{BUYER} AND STATUS <> 'D')
	AND BUYER_ITEM_NO = #{REG_ITEM_NO}
	AND STATUS IN ('C','R')


			UPDATE ICOMCQDT /*updateNsApproval_CQDTMulti*/
				SET BUYER_ITEM_NO = #{BUYER_ITEM_NO}
			WHERE BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE=#{BUYER} AND STATUS <> 'D')
				AND BUYER_ITEM_NO = #{REG_ITEM_NO}
				AND CONTRACT_NO = #{CONTRACT_NO}
				AND STATUS IN ('C','R')
				AND (BELOW_COMORG_CODE IN (SELECT BL.COMORG_CODE
                                                                 FROM BYCAORGL BL, ICOMCMPY CP
                                                                WHERE BL.P_COMORG_CODE  IN (SELECT P_COMORG_CODE
                                                                                                            FROM BYCAORGL 
                                                                                                            WHERE COMORG_CODE = #{BUYER})
                                                                   AND BL.COMORG_CODE = CP.COM_CODE
                                                                   AND CP.STATUS IN ('C','R') 
                                                                   AND #{BELOW_COMORG_CODE} = 'ALL')
                        OR  BELOW_COMORG_CODE=#{BELOW_COMORG_CODE}
                		)


UPDATE KEPRQDT    /*updateNsRejectMulti*/
       SET RECV_FLAG = #{RECV_FLAG}
    WHERE BUYER = #{KEY_2}
      AND GW_NO = #{KEY_1}
      AND STATUS IN ('C','R')

mapper.select:

			SELECT DISTINCT BELOW_COMORG_CODE /*getAboveFlagMulti*/
              FROM KEPRQDT
              WHERE BUYER =  #{KEY_2}
               AND GW_NO =  #{KEY_1}
               AND STATUS<>'D'


		 /*selectOrgCodeMulti*/
			SELECT CASE WHEN COM_CODE = BYCA_COMORG_CODE THEN COM_CODE
            			ELSE BYCA_COMORG_CODE END BUYER
              FROM ICOMCMPY
			 WHERE COM_CODE = #{BUYER}


			SELECT PASS_FLAG /*getPassFlagMulti*/  
              FROM ICOMCMPY       
              WHERE COM_CODE = #{st_buyer2}


SELECT COUNT(*) AS CNT /*getPassCheckMulti*/
  FROM ICOGPASS 
WHERE COMPANY = #{st_buyer2} 
    AND DOCU_TYPE = #{DOC_TYPE}

