UPDATE KEPRQDT			/*updateBuyerItemNoMulti*/		
   SET BUYER_ITEM_NO = #{st_buyer_item_no3}	
   		, BUYER_TARGET_PRICE=#{st_target_price}	
 WHERE BUYER         = #{st_buyer2}
   AND QUOTATION_NO  = #{st_quotation_no2}
   AND QUOTATION_SEQ = #{st_quotation_seq2}
   AND REVISION      = #{st_revision2}
   AND STATUS IN ('C','R')


UPDATE KEPRQDT			/*updateCloseRqdtMulti*/		
   SET CONFIRM_USER_ID = #{st_confirm_user_id2}	
   		, BUYER_CANCEL_DATE= TO_CHAR(SYSDATE, 'YYYYMMDD')
   		, BUYER_CANCEL_TIME=TO_CHAR(SYSDATE, 'HH24MISS')
   		, RECV_FLAG = #{st_recv_flag}	
   		, BUYER_CANCEL_REASON = #{st_close_remark}	
 WHERE BUYER         = #{st_buyer2}
   AND QUOTATION_NO  = #{st_quotation_no2}
   AND QUOTATION_SEQ = #{st_quotation_seq2}
   AND REVISION      = #{st_revision2}
   AND STATUS IN ('C','R')


UPDATE ICOMBYIT A		/*updateCloseByitMulti*/		
   SET A.PRODUCT_CLOSE_FLAG = 'C'
WHERE BUYER         = #{st_buyer2}
  AND BUYER_ITEM_NO  = #{st_buyer_item_no3}
